457	func getDeleteUserAttachmentStorageSetting(ctx context.Context, stores *store.Store, attachments []*store.Attachment) (*storepb.InstanceStorageSetting, error) {
458		for _, attachment := range attachments {
459			if store.AttachmentNeedsInstanceStorageSetting(attachment) {
460				instanceStorageSetting, err := stores.GetInstanceStorageSetting(ctx)
461				if err != nil {
462					return nil, errors.Wrap(err, "failed to get instance storage setting")
463				}
464				return instanceStorageSetting, nil
465			}
466		}
467		return nil, nil
468	}
